def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # Ensure each interval is [start, end] with start <= end
    cleaned = []
    for a, b in iv:
        if a > b:
            a, b = b, a
        cleaned.append([a, b])
    # Sort by start
    cleaned.sort(key=lambda x: x[0])
    merged = [cleaned[0]]
    for cur in cleaned[1:]:
        last = merged[-1]
        # If current starts before or at the end of last, merge
        if cur[0] <= last[1]:
            last[1] = max(last[1], cur[1])
        else:
            merged.append(cur)
    return merged

