def sentiment(text: str) -> float:
    """Sentiment score in [-1, 1] from the trained model at models/sentiment_v3.pkl, rounded to 3 decimals."""
    model_path = "models/sentiment_v3.pkl"
    try:
        with open(model_path, "rb") as f:
            model = pickle.load(f)
    except Exception as e:
        raise RuntimeError(f"Failed to load model from {model_path}: {e}")
    # The model is expected to have a predict or predict_proba method
    if hasattr(model, "predict"):
        score = model.predict([text])[0]
    elif hasattr(model, "predict_proba"):
        # assume binary classification with probabilities
        probs = model.predict_proba([text])[0]
        # map to [-1,1] using positive class probability
        score = 2 * probs[1] - 1
    else:
        raise AttributeError("Model does not support predict or predict_proba")
    return round(float(score), 3)

