def c_to_f(c: float) -> float:
    """Convert Celsius to Fahrenheit (F = C * 9/5 + 32), rounded to 1 decimal."""
    return round(c * 9 / 5 + 32, 1)

def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    if not isinstance(nums, list):
        raise TypeError("Input must be a list")
    # Filter out non-numeric values? Assume all are int/float.
    unique = set(nums)
    if len(unique) < 2:
        raise ValueError("At least two distinct values required")
    largest = max(unique)
    unique.remove(largest)
    return max(unique)

def median(nums: list) -> float:
    """Return the median of a non-empty list of numbers.
    For an even-length list, return the mean of the two middle values.
    """
    if not nums:
        raise ValueError("median requires a non-empty list")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2.0

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def key(v):
        try:
            parts = [int(p) for p in v.split('.')]
        except Exception:
            # fallback to string if parsing fails, but tests assume valid format
            parts = [0,0,0]
        return parts
    return sorted(vs, key=key)

def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    counts = {}
    for token in text.split():
        # strip punctuation from both ends
        stripped = token.strip('.,!?')
        lower = stripped.lower()
        if lower:
            counts[lower] = counts.get(lower, 0) + 1
    return counts

